package com.nse.dashboard.agent;import com.nse.dashboard.model.OptionData;import org.springframework.stereotype.Component;import java.util.*;@Component public class TrapAgent { public String detect(List<OptionData> data){ int callWriting=0,putBuying=0; for(OptionData d:data){ if(d.getCallBuiltUp().contains("Writing"))callWriting++; if(d.getPutBuiltUp().contains("Buying"))putBuying++;} if(callWriting>5&&putBuying>5)return"High Trap"; return"Low Trap";}}